"""Negative checks for file-origin provider capture authorization and private static auth."""
from __future__ import annotations
import os
import sys
from pathlib import Path
from types import SimpleNamespace
from urllib import request, error
import http.server
import threading
import tempfile
ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT))
from server_modules import audioflix_provider_file_auth as file_auth
# All credentials generated by the test stay in an isolated temp tree.
# Never rewrite the running EveOS server's real data/runtime credential!
_test_dir = tempfile.TemporaryDirectory(prefix='eveos-file-auth-test-')
file_auth.ROOT = Path(_test_dir.name)
file_auth.SCRIPT_PATH = Path(_test_dir.name) / 'data' / 'runtime' / 'audioflix-provider-file-auth.js'
import types
cors=types.ModuleType("server_modules.eveos_http_cors")
cors.eveos_cors_origin=lambda origin: "*" if origin == "null" else origin
sys.modules["server_modules.eveos_http_cors"] = cors
from server_modules.eveos_http_headers import EveOSHTTPHeadersMixin
# Avoid audio device initialization in this server-side auth-only smoke.
import types
fake = types.ModuleType('server_modules.audioflix_bridge_playback')
for name in ('clear_voices','get_voice_debug','play_media','play_pcm','play_tone','play_voice','pause_voices','set_voice_volume','stop_stream','warm'):
    setattr(fake,name,lambda *_args,**_kwargs: {})
sys.modules['server_modules.audioflix_bridge_playback'] = fake
fake = types.ModuleType('server_modules.audioflix_bridge_devices')
fake.list_devices=lambda **kw: {}
sys.modules['server_modules.audioflix_bridge_devices'] = fake
from server_modules.audioflix_bridge import _can_start_provider_capture

file_auth.initialize()
_original_key = file_auth._KEY
file_auth.initialize()
assert file_auth._KEY == _original_key, 'test imports/restarts must not rotate an existing authorization key'
assert file_auth.SCRIPT_PATH.is_file()
assert 'window.__EveOSProviderFileAuth' in file_auth.SCRIPT_PATH.read_text()

class Static(EveOSHTTPHeadersMixin,http.server.SimpleHTTPRequestHandler):
    def __init__(self,*args,**kwargs):
        super().__init__(*args,directory=str(file_auth.ROOT),**kwargs)
    def log_message(self,*_):pass

server=http.server.HTTPServer(('127.0.0.1',0),Static)
thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
try:
    private_paths = (
        'data/runtime/agent-management/agents.json',
        'data/runtime/nexus-browser/dex-state.json',
        'config/agents/tlo/session.json',
        'config/agents/iris/AGENT.md',
        'nested/.claude/projects/session.jsonl',
        'AGENTS.override.md',
    )
    for name in (*private_paths, 'config/agents/tlo/AGENT.md'):
        fixture = file_auth.ROOT / name
        fixture.parent.mkdir(parents=True, exist_ok=True)
        fixture.write_text('synthetic fixture', encoding='utf-8')
    denied = (
        '/data/runtime/audioflix-provider-file-auth.js',
        *(f'/{name}' for name in private_paths),
        '/data/%72untime/agent-management/agents.json',
        '/data/runtime/',
        '/data/',
    )
    for method in ('GET','HEAD'):
        for name in denied:
            req=request.Request(f'http://127.0.0.1:{server.server_port}{name}',method=method)
            try: request.urlopen(req,timeout=4);raise AssertionError(f'Private path served over HTTP: {name}')
            except error.HTTPError as e: assert e.code==404,e.code
        req = request.Request(f'http://127.0.0.1:{server.server_port}/config/agents/tlo/AGENT.md', method=method)
        with request.urlopen(req, timeout=4) as response:
            assert response.status == 200
finally:
    server.shutdown();thread.join(timeout=3);server.server_close()

class Headers(dict):
    def get(self,key,default=None):
        return super().get(key,default)

local = f'127.0.0.1:{server.server_port}'
def allowed(origin,proof='',site='cross-site'):
    h=Headers({'Content-Type':'application/json','X-EveOS-Provider-Capture':'v1','Host':local,'Origin':origin,'Sec-Fetch-Site':site})
    if proof: h['X-EveOS-Provider-File-Auth']=proof
    return _can_start_provider_capture(SimpleNamespace(headers=h,server=SimpleNamespace(server_address=('127.0.0.1',server.server_port)),client_address=('127.0.0.1',0)))
assert allowed('null',file_auth._KEY),'installed local file should be allowed'
assert not allowed('null',''),'opaque-origin without proof forbidden'
assert not allowed('null','wrong'),'incorrect proof forbidden'
assert not allowed('','',site=''),'origin-omitting file request without proof forbidden'
assert allowed('',file_auth._KEY,site=''),'verified Chromium file request with omitted origin permitted'
assert not allowed('file://',''),'file origin without proof forbidden'
assert allowed('file://',file_auth._KEY),'verified Chromium file origin permitted'
assert not allowed('https://example.com',file_auth._KEY),'foreign origin forbidden'
assert allowed(f'http://{local}',site='same-origin'),'same-origin localhost must remain working'
assert not allowed(f'http://{local}',site='cross-site'),'cross-site localhost forbidden'
print('AUDIOFLIX_PROVIDER_FILE_DIRECT_SECURITY_OK private_static_denied=true file_proof_required=true foreign_denied=true localhost_preserved=true')

_test_dir.cleanup()
